const fs = require('fs');

function main() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function nextInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;

        let sign = 1;
        if (buffer[offset] === 45) { // '-'
            sign = -1;
            offset++;
        }

        let num = 0;
        while (offset < buffer.length && buffer[offset] >= 48 && buffer[offset] <= 57) {
            num = num * 10 + (buffer[offset] - 48);
            offset++;
        }
        return sign * num;
    }

    const A = nextInt();
    if (A === null) return;
    const B = nextInt();

    const SA = new Int32Array(A);
    for (let i = 0; i < A; i++) {
        SA[i] = nextInt();
    }

    let ptrB = 0;
    let target = nextInt();

    for (let i = 0; i < A; i++) {
        if (SA[i] === target) {
            ptrB++;
            if (ptrB === B) {
                break;
            }
            target = nextInt();
        }
    }

    if (ptrB === B) {
        console.log('S');
    } else {
        console.log('N');
    }
}

main();
